mapper.select:
SELECT 1- COUNT(1) FROM DUAL WHERE EXISTS (SELECT 1 FROM LA_ROLE_RESOURCES T
INNER JOIN LA_RESOURCES T2 ON T.RESOURCEID = T2.ID
WHERE T.AUTHORITY = #{authority}

    AND T.TENANT_ID = #{tenant_id, jdbcType=VARCHAR}

AND (T2.PARENTKEYS LIKE CONCAT('%', CONCAT(#{id}, '-%')) OR T2.PARENTID = #{id}))
